using IndieRun;
using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using System.Xml.Linq;
class Program
{
    static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
    static void Set(object o,string field,object? value)=>o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(o,value);
    static T Get<T>(object o,string field)=>(T)o.GetType().GetField(field,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(o)!;
    static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static Package Fixture(string dir,bool selective=false)
    {
        var folder=Path.Combine(dir,"input","GeneratedGame");Directory.CreateDirectory(Path.Combine(folder,"Data"));Directory.CreateDirectory(Path.Combine(folder,"Extras"));
        File.WriteAllText(Path.Combine(folder,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllBytes(Path.Combine(folder,"Data","large.bin"),Enumerable.Range(0,1536*1024).Select(i=>(byte)(i%251)).ToArray());File.WriteAllText(Path.Combine(folder,"Extras","guide.txt"),"kept or moved according to selection");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=folder,DetectedRoot=folder,SearchRoot=Path.Combine(dir,"input"),Name="GeneratedGame",Folder="GeneratedGame",Alias="가상 게임"};if(selective)p.OmittedFolders.Add("Extras");return p;
    }
    static MainWindow Window(string dir,out Package p)
    {
        p=Fixture(dir);var scan=GameScanner.Scan(p.SearchRoot);scan.PrepareIndex();var plan=new WorkspaceDocument{SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=[p],Checkpoints=[WorkspaceReconciler.Capture(p,scan)]};var store=new WorkspaceStore(Path.Combine(dir,"data","workspace.json"));store.Save(plan);
        var w=new MainWindow();new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();Set(w,"workspaceStore",store);Set(w,"workspaceLock",store.AcquireLock());Call(w,"ApplyWorkspace",plan);Set(w,"snapshot",scan);Set(w,"sessionReady",true);Set(w,"playerRoot",plan.Destination);Set(w,"playerDocument",new PlayerDocument());Set(w,"directEngineFactory",(Func<BackupEngine>)(()=>new(Path.Combine(dir,"records"))));return w;
    }
    static void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
    static IEnumerable<DependencyObject> Logical(DependencyObject root){yield return root;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var nested in Logical(child))yield return nested;}
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Click(Button b)=>b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
    static void Toggle(System.Windows.Controls.Primitives.ToggleButton b,bool value){b.IsChecked=value;b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
    static Button FindButton(Window w,string text)=>Logical((DependencyObject)w.Content).OfType<Button>().Single(b=>b.Content as string==text);
    static T Named<T>(Window w,string name)where T:FrameworkElement=>Logical((DependencyObject)w.Content).OfType<T>().Single(e=>e.Name==name);
    static void Layout(Window w,double width,double height,string file){var body=(FrameworkElement)w.Content;body.Measure(new Size(width,height));body.Arrange(new Rect(0,0,width,height));body.UpdateLayout();foreach(var b in Logical(body).OfType<Button>().Where(b=>b.IsVisible||b.ActualWidth>0)){var point=b.TranslatePoint(new Point(),body);Check(point.X>=-1&&point.X+b.ActualWidth<=width+1,"Button clipped horizontally: "+b.Content);}var bitmap=new RenderTargetBitmap((int)width,(int)height,96,96,PixelFormats.Pbgra32);var bg=new DrawingVisual();using(var draw=bg.RenderOpen())draw.DrawRectangle(w.Background,null,new Rect(0,0,width,height));bitmap.Render(bg);bitmap.Render(body);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(file);png.Save(output);}
    static Package Second(MainWindow w,string dir){var p=Fixture(Path.Combine(dir,"second"));p.Alias="두 번째 가상 게임";Get<List<Package>>(w,"packages").Add(p);var scan=GameScanner.Scan(dir);Set(w,"snapshot",scan);Set(w,"checkpoints",Get<List<Package>>(w,"packages").Select(g=>WorkspaceReconciler.Capture(g,scan)).ToList());return p;}
    static IntakeSelection Plan(MainWindow w,List<Package> games)=>new(new MoveSelection(games,Get<List<Package>>(w,"packages")));
    static LibraryDocument Registered(Package p)=>new(){Games=[new(){Id=p.Id,Folder=p.Folder,LastKnownPath=p.Source,Executables=["Game.exe"],Scope=StoredScope.Capture(p)}]};
    static (Package Game,string Parent,string Search,ScanSnapshot Scan,FolderCheckpoint Checkpoint) Game(string dir,bool marked=true)
    {
        var search=Path.Combine(dir,"container");var parent=Path.Combine(search,"外側パッケージ","ゲーム名");var data=Path.Combine(parent,"data");Directory.CreateDirectory(data);File.WriteAllText(Path.Combine(data,"Game.exe"),"harmless generated fixture; never execute");File.WriteAllText(Path.Combine(data,"save.dat"),"test save");
        var p=new Package{Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=marked,Source=data,DetectedRoot=data,SearchRoot=search,Name="data",Folder="data"};if(marked)LibraryStore.EnsureIdentity(data,p.Id);var scan=GameScanner.Scan(search);scan.SearchRoots.Add(search);scan.PrepareIndex();return(p,parent,search,scan,WorkspaceReconciler.Capture(p,scan));
    }
    static string RenameParent(string parent){var renamed=Path.Combine(Path.GetDirectoryName(parent)!,"ゲーム名5555");Directory.Move(parent,renamed);return Path.Combine(renamed,"data");}
    static string Refusal(Action run){try{run();}catch(IOException e){return e.Message;}throw new Exception("Expected refusal");}
    static WorkspaceDocument Plan(string dir,Package p,FolderCheckpoint check,params Package[] others)=>new(){SearchRoot=p.SearchRoot,SearchLocations=[new(){Path=p.SearchRoot}],Destination=Path.Combine(dir,"library"),BackupRoot=Path.Combine(dir,"backups"),Packages=new[]{p}.Concat(others).ToList(),Checkpoints=[check]};
    static Package Helper(string parent)=>new(){Id=Guid.NewGuid().ToString("N"),IsReal=true,Registered=false,Source=parent,DetectedRoot=parent,SearchRoot=Path.GetDirectoryName(parent)!,Folder=Path.GetFileName(parent),Name=Path.GetFileName(parent)};
    static ScanSnapshot Scan(string root){var scan=GameScanner.Scan(root);scan.SearchRoots.Add(root);scan.PrepareIndex();return scan;}
    [STAThread]static int Main(string[] args)
    {
        var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());
        void Test(string name,Action<string> action){try{var dir=Path.Combine(root,name);Directory.CreateDirectory(dir);action(dir);results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+" "+ex.Message);}}
        Test("search-boundary-can-be-game-scope",dir=>{var f=Game(dir,false);f.Game.SearchRoot=f.Parent;Check(ScopeChange.Problem(f.Game,f.Parent,[f.Game],f.Scan)==null,"Exact search boundary refused");});
        Test("drive-root-is-never-game-scope",dir=>{var f=Game(dir,false);f.Game.SearchRoot=Path.GetPathRoot(dir)!;Check(ScopeChange.Problem(f.Game,f.Game.SearchRoot,[f.Game],f.Scan)!=null,"Drive root accepted");});
        Test("library-root-is-never-game-scope",dir=>{var f=Game(dir,false);File.WriteAllText(Path.Combine(f.Parent,LibraryStore.JsonName),"{}");Check(ScopeChange.Problem(f.Game,f.Parent,[f.Game],f.Scan)!=null,"Library metadata container accepted");});
        Test("registered-scope-commit-and-recovery-at-search-boundary",dir=>{var f=Game(dir);f.Game.SearchRoot=f.Parent;var plan=Plan(dir,f.Game,f.Checkpoint);var lib=Registered(f.Game);new LibraryStore(plan.Destination).Update(d=>d.Games=lib.Games);var data=Path.Combine(dir,"data");var service=new ScopeChange(data);var record=service.Prepare(plan,new(),new(),lib,f.Game.Id,f.Parent);service.Checkpoint=phase=>{if(phase=="new-marker")throw new IOException("generated interruption");};Refusal(()=>service.Commit(record));Check(service.HasPending,"Scope intent lost");new ScopeChange(data).Recover();Check(LibraryStore.ReadIdentity(f.Parent)?.GameId==f.Game.Id&&LibraryStore.ReadIdentity(f.Game.Source)==null,"Marker recovery failed");Check(new WorkspaceStore(Path.Combine(data,"workspace.json")).Load().Document!.Packages.Single().Source==f.Parent,"Scope save not replayed");});
        Test("auto-rename-keeps-search-boundary-and-retires-old-history",dir=>{var f=Game(dir);var next=RenameParent(f.Parent);var scan=Scan(f.Search);f.Game.CompositionMoveState="old-completed-move";IdentityReconciler.Rebind(new(){f.Game},new(){f.Checkpoint},Registered(f.Game),LibraryStore.Inspect(scan),scan,Path.Combine(dir,"library"));Check(f.Game.Source==next&&f.Game.SearchRoot==f.Search,"Search scope shrank");Check(f.Game.CompositionMoveState.StartsWith("Reconnected:"),"Old move evidence still authoritative");});
        Test("auto-rename-absorbs-passive-helper-ancestor",dir=>{var f=Game(dir);var next=RenameParent(f.Parent);var parent=Path.GetDirectoryName(next)!;File.WriteAllText(Path.Combine(parent,"unins000.exe"),"generated helper");var helper=Helper(parent);var scan=Scan(f.Search);var games=new List<Package>{f.Game,helper};var checks=new List<FolderCheckpoint>{f.Checkpoint,WorkspaceReconciler.Capture(helper,scan)};IdentityReconciler.Rebind(games,checks,Registered(f.Game),LibraryStore.Inspect(scan),scan,Path.Combine(dir,"library"));Check(f.Game.Source==next&&games.Count==1&&checks.Count==1,"Helper candidate blocked known ID");});
        Test("configured-helper-is-not-absorbed",dir=>{var f=Game(dir);var next=RenameParent(f.Parent);var helper=Helper(Path.GetDirectoryName(next)!);helper.Alias="사용자 지정";helper.ScopeHistory.Add(f.Game.Source);var scan=Scan(f.Search);var games=new List<Package>{f.Game,helper};IdentityReconciler.Rebind(games,new(){f.Checkpoint},Registered(f.Game),LibraryStore.Inspect(scan),scan,Path.Combine(dir,"library"));Check(f.Game.Source!=next&&games.Contains(helper),"User metadata discarded");});
        Test("favorite-candidate-is-not-absorbed",dir=>{var f=Game(dir);var next=RenameParent(f.Parent);var helper=Helper(Path.GetDirectoryName(next)!);var scan=Scan(f.Search);var games=new List<Package>{f.Game,helper};IdentityReconciler.Rebind(games,new(){f.Checkpoint},Registered(f.Game),LibraryStore.Inspect(scan),scan,Path.Combine(dir,"library"),new HashSet<string>{helper.Id});Check(f.Game.Source==next&&games.Contains(helper),"Ancestor settings record discarded or ID rebind blocked");});
        Test("independent-executable-ancestor-is-not-absorbed",dir=>{var f=Game(dir);var next=RenameParent(f.Parent);var helper=Helper(Path.GetDirectoryName(next)!);File.WriteAllText(Path.Combine(helper.Source,"OtherGame.exe"),"generated other game");var scan=Scan(f.Search);var games=new List<Package>{f.Game,helper};IdentityReconciler.Rebind(games,new(){f.Checkpoint},Registered(f.Game),LibraryStore.Inspect(scan),scan,Path.Combine(dir,"library"));Check(f.Game.Source==next&&games.Contains(helper)&&File.Exists(Path.Combine(helper.Source,"OtherGame.exe")),"Ancestor executable or candidate record was absorbed");});
        Test("manual-reconnect-accepts-passive-ancestor-with-fresh-context",dir=>{var f=Game(dir);var next=RenameParent(f.Parent);var helper=Helper(Path.GetDirectoryName(next)!);File.WriteAllText(Path.Combine(helper.Source,"unins000.exe"),"generated helper");var plan=ReconnectPlanner.PrepareWithContext(Plan(dir,f.Game,f.Checkpoint,helper),f.Game.Id,next,Scan(next),Registered(f.Game),new(),Scan(f.Search));Check(plan.Packages.Count==1&&plan.Packages.Single().Source==next,"False registered overlap remains");});
        Test("manual-reconnect-resolves-container-to-unique-game-id",dir=>{var f=Game(dir);var next=RenameParent(f.Parent);var parent=Path.GetDirectoryName(next)!;var plan=ReconnectPlanner.Prepare(Plan(dir,f.Game,f.Checkpoint),f.Game.Id,parent,Scan(parent),Registered(f.Game),new());Check(plan.Packages.Single().Source==next,"Container was connected instead of identified game");});
        Test("foreign-id-is-never-overwritten",dir=>{var f=Game(dir);var other=Game(Path.Combine(dir,"other"));var before=File.ReadAllBytes(Path.Combine(other.Game.Source,LibraryStore.MarkerName));Refusal(()=>ReconnectPlanner.Prepare(Plan(dir,f.Game,f.Checkpoint),f.Game.Id,other.Game.Source,Scan(other.Game.Source),Registered(f.Game),new()));Check(before.SequenceEqual(File.ReadAllBytes(Path.Combine(other.Game.Source,LibraryStore.MarkerName))),"Foreign ID mutated");});
        Test("partial-copy-scan-keeps-existing-original",dir=>{var f=Game(dir);var original=f.Game.Source;var copy=Path.Combine(dir,"copy");Directory.CreateDirectory(copy);foreach(var file in Directory.GetFiles(original))File.Copy(file,Path.Combine(copy,Path.GetFileName(file)));var scan=Scan(copy);var inv=LibraryStore.Inspect(scan);IdentityReconciler.Rebind(new(){f.Game},new(){f.Checkpoint},Registered(f.Game),inv,scan,Path.Combine(dir,"library"));Check(f.Game.Source==original&&inv.Locations[f.Game.Id].Count==2,"Copy stole original connection");});
        Test("duplicate-renamed-copies-remain-unresolved",dir=>{var f=Game(dir);var next=RenameParent(f.Parent);var copy=Path.Combine(dir,"copy");Directory.CreateDirectory(copy);foreach(var file in Directory.GetFiles(next))File.Copy(file,Path.Combine(copy,Path.GetFileName(file)));var scan=Scan(dir);IdentityReconciler.Rebind(new(){f.Game},new(){f.Checkpoint},Registered(f.Game),LibraryStore.Inspect(scan),scan,Path.Combine(dir,"library"));Check(f.Game.Source!=next&&f.Game.Source!=copy,"Ambiguous duplicate chosen");});
        Test("library-location-agrees-when-overlap-blocks-rebind",dir=>{var f=Game(dir);var old=f.Game.Source;var lib=Path.Combine(dir,"library");new LibraryStore(lib).Update(d=>d.Games=Registered(f.Game).Games);var next=RenameParent(f.Parent);var helper=Helper(Path.GetDirectoryName(next)!);helper.Alias="사용자 지정";helper.ScopeHistory.Add(f.Game.Source);var prepared=ScanPreparation.Build(Scan(f.Search),new(){f.Game,helper},new(){f.Checkpoint},[],lib,CancellationToken.None);Check(prepared.Library.Games.Single().LastKnownPath==old&&prepared.Library.Games.Single().Status=="LocationCheck"&&f.Game.ReviewState=="relocation","Library and game path disagree");});
        Test("related-unmarked-sibling-follows-proven-parent-rename",dir=>{var f=Game(dir);var extras=Path.Combine(f.Parent,"Extras");Directory.CreateDirectory(extras);File.WriteAllText(Path.Combine(extras,"guide.txt"),"generated guide");var asset=Helper(extras);asset.IsContent=true;asset.ContentOwnerId=f.Game.Id;f.Game.RelatedFolders.Add(new(){Id=asset.Id,Source=extras,Name="Extras"});var checks=new List<FolderCheckpoint>{f.Checkpoint,WorkspaceReconciler.Capture(asset,Scan(f.Search))};var next=RenameParent(f.Parent);var scan=Scan(f.Search);IdentityReconciler.Rebind(new(){f.Game,asset},checks,Registered(f.Game),LibraryStore.Inspect(scan),scan,Path.Combine(dir,"library"));Check(asset.Source==Path.Combine(Path.GetDirectoryName(next)!,"Extras")&&f.Game.RelatedFolders.Single().Source==asset.Source,"Related sibling kept stale path");});
        Test("changed-related-sibling-is-not-guessed",dir=>{var f=Game(dir);var extras=Path.Combine(f.Parent,"Extras");Directory.CreateDirectory(extras);File.WriteAllText(Path.Combine(extras,"guide.txt"),"generated guide");var asset=Helper(extras);asset.IsContent=true;f.Game.RelatedFolders.Add(new(){Id=asset.Id,Source=extras,Name="Extras"});var checks=new List<FolderCheckpoint>{f.Checkpoint,WorkspaceReconciler.Capture(asset,Scan(f.Search))};var next=RenameParent(f.Parent);File.WriteAllText(Path.Combine(Path.GetDirectoryName(next)!,"Extras","guide.txt"),"a different guide with changed length");var scan=Scan(f.Search);IdentityReconciler.Rebind(new(){f.Game,asset},checks,Registered(f.Game),LibraryStore.Inspect(scan),scan,Path.Combine(dir,"library"));Check(asset.Source==extras,"Changed content guessed as original");});
        Test("internal-launch-directory-requires-explicit-selection",dir=>{var f=Game(dir);var old=Path.Combine(f.Game.Source,"engine");Directory.CreateDirectory(old);Directory.CreateDirectory(Path.Combine(old,"work"));File.Move(Path.Combine(f.Game.Source,"Game.exe"),Path.Combine(old,"Game.exe"));f.Game.DetectedRoot=old;var check=WorkspaceReconciler.Capture(f.Game,Scan(f.Search));var g=new GamePlay{Id=f.Game.Id,Executable=Path.Combine("engine","Game.exe"),WorkingDirectory=Path.Combine("engine","work"),Favorite=true,Arguments="--keep"};Directory.Move(old,Path.Combine(f.Game.Source,"engine-new"));LaunchPathRepair.Apply([f.Game],[check],new(){Games=[g]},Scan(f.Game.Source));Check(g.Executable==Path.Combine("engine","Game.exe")&&g.WorkingDirectory==Path.Combine("engine","work")&&f.Game.ReviewState=="launch"&&g.Favorite&&g.Arguments=="--keep","Launch settings stale or lost");});
        Test("ambiguous-launch-directory-requires-user-selection",dir=>{var f=Game(dir);var old=Path.Combine(f.Game.Source,"engine");Directory.CreateDirectory(old);File.Move(Path.Combine(f.Game.Source,"Game.exe"),Path.Combine(old,"Game.exe"));f.Game.DetectedRoot=old;var check=WorkspaceReconciler.Capture(f.Game,Scan(f.Search));var g=new GamePlay{Id=f.Game.Id,Executable=Path.Combine("engine","Game.exe")};Directory.Move(old,Path.Combine(f.Game.Source,"one"));Directory.CreateDirectory(Path.Combine(f.Game.Source,"two"));File.Copy(Path.Combine(f.Game.Source,"one","Game.exe"),Path.Combine(f.Game.Source,"two","Game.exe"));File.SetLastWriteTimeUtc(Path.Combine(f.Game.Source,"two","Game.exe"),File.GetLastWriteTimeUtc(Path.Combine(f.Game.Source,"one","Game.exe")));LaunchPathRepair.Apply([f.Game],[check],new(){Games=[g]},Scan(f.Game.Source));Check(g.Executable==Path.Combine("engine","Game.exe"),"Ambiguous executable chosen");});
        Test("nested-registration-refuses-before-writing-parent-id",dir=>{var f=Game(dir);var parent=Helper(f.Parent);Refusal(()=>GameRegistration.Add(parent,[],f.Scan,Path.Combine(dir,"library"),false));Check(!File.Exists(Path.Combine(parent.Source,LibraryStore.MarkerName))&&LibraryStore.ReadIdentity(f.Game.Source)?.GameId==f.Game.Id,"Nested identity was written");});
        Test("intentional-split-registration-remains-valid",dir=>{var f=Game(dir,false);var parent=Helper(f.Parent);parent.OmittedFolders.Add("data");LibraryStore.EnsureIdentity(parent.Source,parent.Id);f.Game.CompositionParentId=parent.Id;var scan=Scan(f.Search);GameRegistration.Add(f.Game,[],scan,Path.Combine(dir,"library"),false);Check(LibraryStore.ReadIdentity(f.Game.Source)?.GameId==f.Game.Id&&!FolderPolicy.Overlap(parent,f.Game,parent.Source),"Explicit split blocked");});
        Test("parent-move-range-detects-registered-child",dir=>{var f=Game(dir);var parent=Helper(f.Parent);Check(FolderPolicy.Overlap(parent,f.Game,parent.Source),"Parent move would silently absorb child");parent.OmittedFolders.Add("data");Check(!FolderPolicy.Overlap(parent,f.Game,parent.Source),"Omitted child still blocks move");});
        Test("renamed-search-root-probes-only-sibling-id-paths",dir=>{var f=Game(dir);var old=f.Parent;var next=RenameParent(f.Parent);var map=LocalIdentityProbe.Find([old],[f.Game],[]);Check(map.GetValueOrDefault(old)==Path.GetDirectoryName(next),"Local rename not found");});
        Test("local-probe-does-not-choose-between-copies",dir=>{var f=Game(dir);var old=f.Parent;var next=RenameParent(f.Parent);var other=Path.Combine(Path.GetDirectoryName(old)!,"copy","data");Directory.CreateDirectory(other);File.Copy(Path.Combine(next,LibraryStore.MarkerName),Path.Combine(other,LibraryStore.MarkerName));Check(LocalIdentityProbe.Find([old],[f.Game],[]).Count==0,"Local duplicate was chosen");});
        Test("local-probe-respects-protected-roots",dir=>{var f=Game(dir);var old=f.Parent;var next=RenameParent(f.Parent);Check(LocalIdentityProbe.Find([old],[f.Game],[Path.GetDirectoryName(next)!]).Count==0,"Protected sibling probed");});
        Test("ui-parent-control-visible-at-search-boundary",dir=>{var w=Window(dir,out _);try{var f=Game(dir,false);f.Game.SearchRoot=f.Parent;Set(w,"projectRoot",dir);Set(w,"packages",new List<Package>{f.Game});Set(w,"selected",f.Game);Set(w,"snapshot",f.Scan);Call(w,"Render");Check((bool)Call(w,"CanIncludeParent")!&&((Button)w.FindName("IncludeParentButton")).Visibility==Visibility.Visible,"Parent action hidden");Layout(w,1200,800,Path.Combine(root,"scope-before.png"));Call(w,"SetScope",f.Parent,true);Check(f.Game.Source==f.Parent,"Parent action failed");Layout(w,1200,800,Path.Combine(root,"scope-after.png"));}finally{Close(w);}});
        Test("rescan-integrates-renamed-search-location",dir=>{var w=Window(dir,out _);try{var f=Game(dir);var old=f.Parent;var next=RenameParent(f.Parent);Set(w,"projectRoot",dir);Set(w,"packages",new List<Package>{f.Game});Set(w,"searchLocations",new List<SearchLocation>{new(){Path=old}});Set(w,"destination",Path.Combine(dir,"empty-library"));Set(w,"backupStorageRoot",Path.Combine(dir,"backups"));var read=(Task<ScanSnapshot>)Call(w,"ReadWorkspaceFolders",old,new List<Package>{f.Game},CancellationToken.None)!;Wait(read);Check(read.Result.ContainsDirectory(next)&&read.Result.RecoveredRoots.GetValueOrDefault(old)==Path.GetDirectoryName(next),"Rescan did not include recovered location");}finally{Close(w);}});
        Test("excluded-parent-keeps-registered-child-visible",dir=>{var w=Window(dir,out _);try{var f=Game(dir);var helper=Helper(f.Parent);helper.Excluded=true;Set(w,"projectRoot",dir);Set(w,"searchLocations",new List<SearchLocation>{new(){Path=f.Search}});Set(w,"destination",Path.Combine(dir,"library"));Set(w,"backupStorageRoot",Path.Combine(dir,"backups"));var read=(Task<ScanSnapshot>)Call(w,"ReadWorkspaceFolders",f.Search,new List<Package>{f.Game,helper},CancellationToken.None)!;Wait(read);WorkspaceReconciler.Check(f.Game,f.Checkpoint,read.Result);Check(read.Result.ContainsDirectory(f.Game.Source)&&f.Game.ReviewState=="","Excluded helper hid registered game");}finally{Close(w);}});
        Test("old-backup-location-stays-excluded",dir=>{var w=Window(dir,out _);try{var f=Game(dir);var old=Path.Combine(f.Search,"old-backups");var engine=new BackupEngine(old);Wait(Task.Run(()=>engine.CreateAsync(f.Game,[])));Set(w,"workHistory",new WorkHistoryStore(Path.Combine(dir,"index.json")).Refresh([old]));Set(w,"projectRoot",dir);Set(w,"searchLocations",new List<SearchLocation>{new(){Path=f.Search}});Set(w,"destination",Path.Combine(dir,"library"));Set(w,"backupStorageRoot",Path.Combine(dir,"new-backups"));var read=(Task<ScanSnapshot>)Call(w,"ReadWorkspaceFolders",f.Search,new List<Package>{f.Game},CancellationToken.None)!;Wait(read);Check(!read.Result.Files.Any(f=>GameScanner.Within(f.Path,old))&&LibraryStore.Inspect(read.Result).Locations[f.Game.Id].Count==1,"Old backup entered scan");}finally{Close(w);}});
        Test("backup-copy-id-change-is-refused-without-byte-changes",dir=>{var f=Game(dir);var e=new BackupEngine(Path.Combine(dir,"backups"));BackupJob job=null!;Wait(Task.Run(async()=>job=await e.CreateAsync(f.Game,[])));var payload=e.Payload(job);var bytes=File.ReadAllBytes(Path.Combine(payload,LibraryStore.MarkerName));Refusal(()=>LibraryStore.AssignCopyIdentity(payload,f.Game.Id));Refusal(()=>LibraryStore.EnsureIdentity(payload,f.Game.Id));Check(bytes.SequenceEqual(File.ReadAllBytes(Path.Combine(payload,LibraryStore.MarkerName))),"Backup identity changed");Wait(Task.Run(()=>e.VerifyAsync(job.Id)));});
        Test("known-backup-location-cannot-be-used-as-game-folder",dir=>{var w=Window(dir,out _);try{var old=Path.Combine(dir,"old-backups");Set(w,"workHistory",new WorkHistoryDocument{Roots=[old]});bool denied=false;try{Call(w,"RequireUserGameFolder",Path.Combine(old,"some-game"));}catch(TargetInvocationException ex)when(ex.InnerException is IOException){denied=true;}Check(denied,"Known old backup root allowed");}finally{Close(w);}});
        Test("helper-only-ancestor-is-not-rediscovered-around-registered-game",dir=>{var f=Game(dir);File.WriteAllText(Path.Combine(f.Parent,"unins000.exe"),"generated helper");Check(!WorkspaceReconciler.Discover(Scan(f.Search),[f.Game]).Any(p=>p.Source==f.Parent),"Redundant helper candidate rediscovered");});
        Test("auto-rebind-and-launch-save-replays-after-interruption",dir=>{var f=Game(dir);var lib=Path.Combine(dir,"library");new LibraryStore(lib).Update(d=>d.Games=Registered(f.Game).Games);var plan=Plan(dir,f.Game,f.Checkpoint);var next=RenameParent(f.Parent);var scan=Scan(f.Search);IdentityReconciler.Rebind(plan.Packages,plan.Checkpoints,Registered(f.Game),LibraryStore.Inspect(scan),scan,lib);var data=Path.Combine(dir,"data");var tx=new EditTransaction(data);typeof(EditTransaction).GetProperty("Checkpoint",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(tx,(Action<string>)(phase=>{if(phase=="workspace")throw new IOException("generated save failure");}));Refusal(()=>tx.Commit(new(){Plan=plan,Tags=new(),Play=new(){Games=[new(){Id=f.Game.Id,Favorite=true,Executable="Game.exe"}]},EditedIds=[f.Game.Id],ReconnectedIds=[f.Game.Id]}));Check(File.Exists(tx.Pending),"Durable save intent missing");new EditTransaction(data).Recover();Check(new LibraryStore(lib).Load().Games.Single().LastKnownPath==next&&new PlayerStore(lib).Load().Games.Single().Favorite,"Recovery lost location or player settings");});

        Test("full-rescan-saves-renamed-root-library-and-player-consistently",dir=>{var w=Window(dir,out _);try{var f=Game(dir);var old=f.Parent;f.Game.SearchRoot=old;var plan=Plan(dir,f.Game,f.Checkpoint);plan.SearchRoot=old;plan.SearchLocations=[new(){Path=old}];new LibraryStore(plan.Destination).Update(d=>d.Games=Registered(f.Game).Games);var play=new PlayerDocument{Games=[new(){Id=f.Game.Id,Favorite=true,Executable="Game.exe",Arguments="--keep"}]};new PlayerStore(plan.Destination).Save(play);Call(w,"ApplyWorkspace",plan);Set(w,"playerDocument",play);Set(w,"playerRoot",plan.Destination);Set(w,"projectRoot",dir);var expected=RenameParent(f.Parent);Wait((Task)Call(w,"RefreshWorkspaceAsync",old,false,false)!);var saved=Get<WorkspaceStore>(w,"workspaceStore").Load().Document!;Check(saved.Packages.Single(p=>p.Id==f.Game.Id).Source==expected&&saved.SearchLocations!.Single().Path==Path.GetDirectoryName(expected),"Rescan did not persist recovered path");Check(new LibraryStore(plan.Destination).Load().Games.Single().LastKnownPath==expected&&new PlayerStore(plan.Destination).Load().Games.Single().Favorite,"Library or player desynchronized");Check(!File.Exists(Path.Combine(dir,"data","edit-pending.json")),"Completed intent left pending");}finally{Close(w);}});
        Test("saving-blocked-rebind-keeps-location-check-status",dir=>{var w=Window(dir,out _);try{var f=Game(dir);var lib=Path.Combine(dir,"library");new LibraryStore(lib).Update(d=>d.Games=Registered(f.Game).Games);var old=f.Game.Source;var next=RenameParent(f.Parent);var helper=Helper(Path.GetDirectoryName(next)!);helper.Alias="사용자가 지정한 후보";helper.ScopeHistory.Add(f.Game.Source);var scan=Scan(f.Search);var prepared=ScanPreparation.Build(scan,new(){f.Game,helper},new(){f.Checkpoint},[],lib,CancellationToken.None);Set(w,"projectRoot",dir);Set(w,"packages",prepared.Packages);Set(w,"destination",lib);Set(w,"snapshot",scan);Set(w,"libraryDocument",prepared.Library);Call(w,"SaveLibraryMetadata");var saved=new LibraryStore(lib).Load().Games.Single();Check(saved.LastKnownPath==old&&saved.Status=="LocationCheck","Autosave overrode unresolved location");}finally{Close(w);}});
        Test("registered-child-cannot-be-detached-from-owning-parent",dir=>{var w=Window(dir,out _);try{var f=Game(dir);var parent=Helper(f.Parent);parent.Registered=true;LibraryStore.EnsureIdentity(parent.Source,parent.Id);var scan=Scan(f.Search);Set(w,"projectRoot",dir);Set(w,"packages",new List<Package>{f.Game,parent});Set(w,"selected",f.Game);Set(w,"snapshot",scan);Set(w,"destination",Path.Combine(dir,"library"));Set(w,"backupStorageRoot",Path.Combine(dir,"backups"));var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};bool warned=false;timer.Tick+=(_,_)=>{foreach(var dialog in app.Windows.OfType<Window>().Where(d=>d!=w).ToList()){warned=true;dialog.Close();}};timer.Start();try{Wait((Task)Call(w,"ExecuteMoveListAsync",new List<Package>{f.Game},Path.Combine(dir,"library"))!);}finally{timer.Stop();}Check(warned&&File.Exists(Path.Combine(f.Game.Source,"Game.exe"))&&!Directory.Exists(Path.Combine(dir,"library",parent.Name)),"Child was detached from an owning parent");Check(!Directory.Exists(Path.Combine(dir,"backups"))||!Directory.EnumerateDirectories(Path.Combine(dir,"backups")).Any(),"Backup started before range validation");}finally{Close(w);}});
        Test("auto-rebind-does-not-absorb-new-foreign-child-id",dir=>{var f=Game(dir);var next=RenameParent(f.Parent);var nested=Path.Combine(next,"foreign");Directory.CreateDirectory(nested);LibraryStore.EnsureIdentity(nested,Guid.NewGuid().ToString("N"));var scan=Scan(f.Search);IdentityReconciler.Rebind(new(){f.Game},new(){f.Checkpoint},Registered(f.Game),LibraryStore.Inspect(scan),scan,Path.Combine(dir,"library"));Check(f.Game.Source!=next,"Nested foreign identity was absorbed");});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));return failed==0?0:1;
    }
